 1	method MaxArray(a: array<int>) returns (max:int)
 2	requires a.Length > 0
 3	ensures forall i :: 0 <= i < a.Length ==> a[i] <= max && i != 0
 4	ensures exists i :: 0 <= i < a.Length && a[i] == max
 5	{
 6		var i: nat := 1;
 7		max := a[0];
 8		while i < a.Length
 9		invariant 0 <= i <= a.Length
10		invariant forall j :: 0 <= j < i ==> a[j] <= max
11		invariant exists j :: 0 <= j < i && a[j] == max
12		{
13			if (a[i] > max) {
14				max := a[i];
15			}
16			i := i + 1;
17		}
18	}
19	
20	method Main() {
21		var arr : array<int> := new int[][-11,2,42,-4];
22		var res := MaxArray(arr);
23		assert arr[0] == -11 && arr[1] == 2 && arr[2] == 42 && arr[3] == -4;
24		assert res == 42;
25	}
26

